import{_ as a,c as o,o as n,ae as d}from"./chunks/framework.CgamhPRR.js";const u=JSON.parse('{"title":"Scene","description":"","frontmatter":{},"headers":[],"relativePath":"scene.md","filePath":"scene.md"}'),s={name:"scene.md"};function r(t,e,l,i,c,h){return n(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="scene" tabindex="-1">Scene <a class="header-anchor" href="#scene" aria-label="Permalink to &quot;Scene&quot;">​</a></h1><p>The <code>Scene</code> manages a collection of nodes and provides fast collider lookup using a spatial hash grid.<br> It is responsible only for node management, updates, and collider synchronization.</p><hr><h2 id="scene-responsibilities" tabindex="-1">Scene Responsibilities <a class="header-anchor" href="#scene-responsibilities" aria-label="Permalink to &quot;Scene Responsibilities&quot;">​</a></h2><ul><li>Store and manage <code>SceneNode</code> instances</li><li>Maintain a spatial hash grid for colliders</li><li>Update nodes (<code>update</code>, <code>fixedUpdate</code>)</li><li>Synchronize collider world data</li></ul><hr><h2 id="scene-api" tabindex="-1">Scene API <a class="header-anchor" href="#scene-api" aria-label="Permalink to &quot;Scene API&quot;">​</a></h2><h3 id="addnode-node-scenenode-scenenode" tabindex="-1">addNode(node: SceneNode): SceneNode <a class="header-anchor" href="#addnode-node-scenenode-scenenode" aria-label="Permalink to &quot;addNode(node: SceneNode): SceneNode&quot;">​</a></h3><p>Adds a node to the scene.</p><ul><li>Registers the node internally</li><li>The node becomes part of scene updates</li></ul><hr><h3 id="removenode-node-scenenode" tabindex="-1"><code>removeNode(node: SceneNode)</code> <a class="header-anchor" href="#removenode-node-scenenode" aria-label="Permalink to &quot;`removeNode(node: SceneNode)`&quot;">​</a></h3><p>Removes a node from the scene.</p><ul><li>Detaches the node from the scene</li><li>Does not automatically destroy the node</li></ul><hr><h3 id="findnode-name-string-scenenode-null" tabindex="-1"><code>findNode(name: string): SceneNode | null</code> <a class="header-anchor" href="#findnode-name-string-scenenode-null" aria-label="Permalink to &quot;`findNode(name: string): SceneNode | null`&quot;">​</a></h3><p>Returns the first node with the given name, or <code>null</code> if not found.</p><hr><h3 id="synccolliders" tabindex="-1"><code>syncColliders()</code> <a class="header-anchor" href="#synccolliders" aria-label="Permalink to &quot;`syncColliders()`&quot;">​</a></h3><p>Synchronizes collider data.</p><ul><li>Updates world-space points of all colliders</li><li>Rebuilds the spatial hash grid</li><li>Must be called before rendering and before physics</li></ul><hr><h3 id="update-dt-number" tabindex="-1"><code>update(dt: number)</code> <a class="header-anchor" href="#update-dt-number" aria-label="Permalink to &quot;`update(dt: number)`&quot;">​</a></h3><p>Calls <code>update(dt)</code> on all nodes in the scene.</p><hr><h3 id="fixedupdate-dt-number" tabindex="-1"><code>fixedUpdate(dt: number)</code> <a class="header-anchor" href="#fixedupdate-dt-number" aria-label="Permalink to &quot;`fixedUpdate(dt: number)`&quot;">​</a></h3><p>Calls <code>fixedUpdate(dt)</code> on all nodes in the scene.</p><hr><h1 id="scenenode" tabindex="-1">SceneNode <a class="header-anchor" href="#scenenode" aria-label="Permalink to &quot;SceneNode&quot;">​</a></h1><p><code>SceneNode</code> is the base class for all nodes stored in a scene.<br> Nodes use local transforms and can be parented to other nodes.</p><hr><h2 id="scenenode-properties" tabindex="-1">SceneNode Properties <a class="header-anchor" href="#scenenode-properties" aria-label="Permalink to &quot;SceneNode Properties&quot;">​</a></h2><ul><li><code>id</code> – unique node identifier</li><li><code>name</code> – optional node name</li><li><code>position</code> – local position</li><li><code>angle</code> – local rotation</li><li><code>parent</code> – parent node or <code>null</code></li><li><code>worldPosition</code> – calculated world position</li><li><code>worldAngle</code> – calculated world rotation</li></ul><p>Local transforms are always relative to the parent node.</p><hr><h2 id="scenenode-hierarchy" tabindex="-1">SceneNode Hierarchy <a class="header-anchor" href="#scenenode-hierarchy" aria-label="Permalink to &quot;SceneNode Hierarchy&quot;">​</a></h2><p>Nodes can form parent–child relationships.</p><ul><li>Child transforms are relative to the parent</li><li>World transforms are calculated automatically</li><li>Re-parenting supports preserving world position</li></ul><hr><h2 id="scenenode-api" tabindex="-1">SceneNode API <a class="header-anchor" href="#scenenode-api" aria-label="Permalink to &quot;SceneNode API&quot;">​</a></h2><h3 id="setparent-newparent-scenenode-null-worldpositionstays-boolean-true" tabindex="-1"><code>setParent(newParent: SceneNode | null, worldPositionStays: boolean = true)</code> <a class="header-anchor" href="#setparent-newparent-scenenode-null-worldpositionstays-boolean-true" aria-label="Permalink to &quot;`setParent(newParent: SceneNode | null, worldPositionStays: boolean = true)`&quot;">​</a></h3><p>Sets or removes the parent node.</p><ul><li>If <code>worldPositionStays</code> is <code>true</code>, the node keeps its world transform</li><li>If <code>false</code>, the local transform is preserved</li></ul><hr><h3 id="addnode-node-scenenode-scenenode-1" tabindex="-1"><code>addNode(node: SceneNode): SceneNode</code> <a class="header-anchor" href="#addnode-node-scenenode-scenenode-1" aria-label="Permalink to &quot;`addNode(node: SceneNode): SceneNode`&quot;">​</a></h3><p>Adds a node as a direct child of this node.</p><hr><h3 id="removenode-node-scenenode-1" tabindex="-1"><code>removeNode(node: SceneNode)</code> <a class="header-anchor" href="#removenode-node-scenenode-1" aria-label="Permalink to &quot;`removeNode(node: SceneNode)`&quot;">​</a></h3><p>Removes a direct child node.</p><hr><h3 id="getnodes-nodeclass-function-scenenode" tabindex="-1"><code>getNodes(nodeClass?: Function): SceneNode[]</code> <a class="header-anchor" href="#getnodes-nodeclass-function-scenenode" aria-label="Permalink to &quot;`getNodes(nodeClass?: Function): SceneNode[]`&quot;">​</a></h3><p>Returns all descendant nodes.</p><ul><li>If <code>nodeClass</code> is provided, only nodes of that type are returned</li></ul><hr><h3 id="getnodesfromparent-nodeclass-function-scenenode" tabindex="-1"><code>getNodesFromParent(nodeClass?: Function): SceneNode[]</code> <a class="header-anchor" href="#getnodesfromparent-nodeclass-function-scenenode" aria-label="Permalink to &quot;`getNodesFromParent(nodeClass?: Function): SceneNode[]`&quot;">​</a></h3><p>Returns only direct child nodes.</p><ul><li>Optional filtering by node class</li></ul><hr><h2 id="node-lifecycle-methods" tabindex="-1">Node Lifecycle Methods <a class="header-anchor" href="#node-lifecycle-methods" aria-label="Permalink to &quot;Node Lifecycle Methods&quot;">​</a></h2><p>Custom nodes can override the following methods:</p><ul><li><code>start()</code> – called once when the node is added to a scene</li><li><code>update(dt)</code> – called every scene update</li><li><code>fixedUpdate(dt)</code> – called every scene fixed update</li><li><code>destroy()</code> – cleanup logic when the node is destroyed</li></ul><hr><h2 id="node-messaging-system" tabindex="-1">Node Messaging System <a class="header-anchor" href="#node-messaging-system" aria-label="Permalink to &quot;Node Messaging System&quot;">​</a></h2><p>Nodes can communicate using a message-based system.</p><p>Messages are identified by string types and can carry arbitrary arguments.</p><hr><h3 id="emitmessage-type-string-args-any" tabindex="-1"><code>emitMessage(type: string, ...args: any)</code> <a class="header-anchor" href="#emitmessage-type-string-args-any" aria-label="Permalink to &quot;`emitMessage(type: string, ...args: any)`&quot;">​</a></h3><p>Emits a message from the node.</p><hr><h3 id="addmessagehandler-type-string-handler-messagehandler-options-messagehandleroptions" tabindex="-1"><code>addMessageHandler(type: string, handler: MessageHandler, options?: MessageHandlerOptions)</code> <a class="header-anchor" href="#addmessagehandler-type-string-handler-messagehandler-options-messagehandleroptions" aria-label="Permalink to &quot;`addMessageHandler(type: string, handler: MessageHandler, options?: MessageHandlerOptions)`&quot;">​</a></h3><p>Registers a handler for a message type.</p><h3 id="messagehandleroptions" tabindex="-1">MessageHandlerOptions <a class="header-anchor" href="#messagehandleroptions" aria-label="Permalink to &quot;MessageHandlerOptions&quot;">​</a></h3><ul><li><code>once</code> – if <code>true</code>, the handler is removed after the first call</li></ul><hr><h3 id="removemessagehandler-type-string-handler-messagehandler" tabindex="-1"><code>removeMessageHandler(type: string, handler: MessageHandler)</code> <a class="header-anchor" href="#removemessagehandler-type-string-handler-messagehandler" aria-label="Permalink to &quot;`removeMessageHandler(type: string, handler: MessageHandler)`&quot;">​</a></h3><p>Removes a previously registered message handler.</p>',76)])])}const m=a(s,[["render",r]]);export{u as __pageData,m as default};
